import sys

def main():
    import sys
    import math

    def read_ints():
        return map(int, sys.stdin.readline().split())

    T = next(read_ints())
    results = []

    for _ in range(T):
        N, K = read_ints()
        # Calculate the minimum number of pizzas needed
        pizzas = math.ceil(N / K)
        results.append(pizzas)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
